CREATE SCHEMA IF NOT EXISTS amcservice;
SET search_path TO amcservice;
CREATE TABLE tenants(id uuid PRIMARY KEY,code varchar(40) UNIQUE NOT NULL,name varchar(150) NOT NULL,logo_url text,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY,tenant_id uuid REFERENCES tenants(id),username varchar(80) UNIQUE NOT NULL,password_hash varchar(100) NOT NULL,display_name varchar(120) NOT NULL,role varchar(20) NOT NULL CHECK(role IN('OWNER','ADMIN','EMPLOYEE')),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customers(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),name varchar(150) NOT NULL,phone varchar(20) NOT NULL,address text,dob date,anniversary date,lifetime_value numeric(12,2) NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,phone));
CREATE TABLE catalog_items(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),type varchar(20) NOT NULL CHECK(type IN('PRODUCT','SERVICE')),name varchar(160) NOT NULL,description text,price numeric(12,2) NOT NULL CHECK(price>=0),duration_months int CHECK(duration_months>0),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE packages(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),name varchar(160) NOT NULL,description text,price numeric(12,2) NOT NULL CHECK(price>=0),duration_months int NOT NULL CHECK(duration_months>0),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE package_items(package_id uuid REFERENCES packages(id) ON DELETE CASCADE,catalog_item_id uuid REFERENCES catalog_items(id),quantity int NOT NULL DEFAULT 1 CHECK(quantity>0),PRIMARY KEY(package_id,catalog_item_id));
CREATE SEQUENCE bill_number_seq START 1001;
CREATE TABLE orders(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),customer_id uuid NOT NULL REFERENCES customers(id),bill_number varchar(40) UNIQUE NOT NULL,status varchar(20) NOT NULL DEFAULT 'PAID',subtotal numeric(12,2) NOT NULL,discount numeric(12,2) NOT NULL,total numeric(12,2) NOT NULL,payment_method varchar(20) NOT NULL CHECK(payment_method IN('UPI','CASH','ZERO')),created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE order_items(id uuid PRIMARY KEY,order_id uuid NOT NULL REFERENCES orders(id) ON DELETE CASCADE,item_kind varchar(20) NOT NULL,item_id uuid NOT NULL,description varchar(200) NOT NULL,unit_price numeric(12,2) NOT NULL,quantity int NOT NULL,discount numeric(12,2) NOT NULL DEFAULT 0,duration_months int,service_expires_on date);
CREATE TABLE whatsapp_configs(id uuid PRIMARY KEY,tenant_id uuid UNIQUE NOT NULL REFERENCES tenants(id),phone_number varchar(20) NOT NULL,provider varchar(40) NOT NULL,secret_reference varchar(200) NOT NULL,automatic_enabled boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification_jobs(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),customer_id uuid NOT NULL REFERENCES customers(id),order_item_id uuid REFERENCES order_items(id),kind varchar(30) NOT NULL,scheduled_for timestamptz NOT NULL,status varchar(20) NOT NULL DEFAULT 'PENDING',message text NOT NULL,idempotency_key varchar(180) UNIQUE NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),sent_at timestamptz);
CREATE TABLE audit_logs(id bigserial PRIMARY KEY,tenant_id uuid,actor_user_id uuid,action varchar(80) NOT NULL,entity_type varchar(60) NOT NULL,entity_id varchar(100),details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX customers_tenant_idx ON customers(tenant_id);CREATE INDEX catalog_tenant_idx ON catalog_items(tenant_id);CREATE INDEX orders_tenant_created_idx ON orders(tenant_id,created_at DESC);CREATE INDEX notifications_due_idx ON notification_jobs(status,scheduled_for);
